fn record_thread_interacted(&mut self, thread_id: &agent_ui::ThreadId, cx: &mut App) {
    let store = ThreadMetadataStore::global(cx);
    store.update(cx, |store, cx| {
        store.update_interacted_at(thread_id, Utc::now(), cx);
    })
}

